```sql
with q4 as (
    select period as label, change as value from doorstep.ch6_by_year where period like '2024Q4'
), q5 as (
    select period as label, change as value from doorstep.ch6_by_year where period like '2025Q4'
), q as (
    select label, max(q4.value) as value from q4 left join q5 on q4.label = q5.label group by label
)
select label as label, case when value > 0 then 'Increase' when value < 0 then 'Decrease' else 'No change' end as value from q
