```sql
with 2015 as (
  select airport as label, sum(cancelled) / sum(scheduled) as value from turnaround.mart_airport_day where airport = 'VX' and year(flight_date) = 2015 group by airport
), 2016 as (
  select airport as label, sum(cancelled) / sum(scheduled) as value from turnaround.mart_airport_day where airport = 'VX' and year(flight_date) = 2016 group by airport
), 2017 as (
  select airport as label, sum(cancelled) / sum(scheduled) as value from turnaround.mart_airport_day where airport = 'VX' and year(flight_date) = 2017 group by airport
)
select label, max(value) as rising from 2015 order by value desc limit 1 UNION ALL select label, min(value) as falling from 2017 order by value limit 1
```

```sql
with cost_2009 as (
  select median_income as price, purchase_median_income as cost, year from doorstep.mart_metro_year where cbsa_title in ('Savannah, GA') and year = 2009
), cost_2024 as (
  select median_income as price, purchase_median_income as cost, year from doorstep.mart_metro_year where cbsa_title in ('Savannah, GA') and year = 2024
), cost_diff as (
  select year, sum(cost) - sum(price) as change from cost_2009, cost_2024 group by year order by change
)
```
